{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량의 이상을 발견한 상황에서 처방대로 투약하기보다 투약을 보류하고 담당자 확인을 우선하는 판단 기준을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력되어 있었다.",
          "task": "처방 용량의 적절성이 확인되지 않은 상태에서 투약 진행 여부를 결정해야 했다.",
          "action": "평소 용량과의 차이를 근거로 처방 확인이 필요하다고 판단하고, 담당의 확인 전에는 투약하지 않는 기준을 적용했다.",
          "result": "담당의 확인으로 입력 오류였음을 확인한 사실은 답변의 맥락을 이해하기 위한 참고로 듣는다."
        },
        "expectedEvidence": [
          "용량의 적절성이 확인되지 않으면 투약을 보류하고 담당의 확인을 우선한다는 판단 기준",
          "해당 진통제 처방이 평소 용량의 두 배였다는 판단 근거"
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔을 때, 처방대로 투약하지 않고 담당의 확인을 먼저 받기로 결정한 기준은 무엇이었나요?",
      "answerTip": "당시 상황을 짧게 소개하고 질문의 초점에 맞춰 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방이 평소 용량의 두 배였다는 상황에 연결하여, 용량의 적절성이 확인되기 전에는 투약을 보류하고 담당의 확인을 우선한다는 기준을 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 처방이 의심스러우면 투약을 보류하고 확인한다는 기준은 제시하지만, 해당 처방 용량의 차이와 연결하지 않고 일반적인 원칙으로 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 보류하고 담당의 확인을 우선한 기준을 제시하지 않거나, 처방 확인 여부와 무관한 투약 경험만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자에게 빠짐없이 전달하기 위해 인수인계 체크리스트에 포함할 정보를 선정하는 기준을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "낙상 고위험 환자 인수인계 체크리스트 개선 활동에서 진통제 투여 시각과 보행 보조 여부 항목을 추가했다.",
          "task": "다음 근무자가 수술 후 환자의 상태를 이어서 파악할 수 있도록 인수인계에 포함할 정보를 선정해야 했다.",
          "action": "교대 후에도 이어서 확인해야 하는 환자 상태 정보라는 기준을 실제 추가 항목에 연결하여 설명한다.",
          "result": "선정한 정보가 인수인계 체크리스트에 반영된 사실은 답변 흐름을 이해하기 위한 참고로 듣는다."
        },
        "expectedEvidence": [
          "다음 근무자에게 전달할 환자 상태 정보를 인수인계 체크리스트에 포함하기로 정한 기준",
          "진통제 투여 시각이나 보행 보조 여부 등 실제 추가 항목에 적용한 선정 기준의 구체적인 설명"
        ]
      },
      "question": "낙상 고위험 환자 인수인계 체크리스트 개선에서 항목을 추가했을 때, 다음 근무자에게 전달할 환자 상태 정보를 체크리스트에 포함하기로 정한 기준은 무엇이었나요?",
      "answerTip": "직접 참여한 범위 안에서 당시의 생각을 차분하게 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "환자 상태 정보의 선정 기준을 진통제 투여 시각이나 보행 보조 여부 등 실제 체크리스트 추가 항목에 연결하여, 다음 근무자가 이어서 확인해야 할 정보의 범위를 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태 정보 중 중요하거나 누락되기 쉬운 내용을 인수인계한다는 선정 기준은 제시하지만, 실제 체크리스트 추가 항목에 적용한 설명은 없다."
          ]
        },
        "poor": {
          "criteria": [
            "인수인계 체크리스트에 포함할 환자 상태 정보의 선정 기준을 제시하지 않거나, 체크리스트 개선 성과 등 다른 이야기만 설명한다."
          ]
        }
      }
    }
  ]
}
